-- Make the Getting there and Swipe tabs follow the chosen destination.
-- 1) Swipe decks get a destination (for the UI) and an optional feature (for access): decks with a feature
--    are only visible to people who hold that grant in feature_access. Cards and swipes inherit that
--    through their policies, so hidden decks leak nothing.
-- 2) Adds a Maldives deck and a Mauritius deck (hidden, granted to Pranjal already via feature_access).
-- 3) Adds a flight/transfer timeline to every Maldives and Mauritius option, used by the Getting there tab.

alter table swipe_decks
  add column if not exists destination text,
  add column if not exists feature text;

update swipe_decks set destination = 'samui' where key = 'honeymoon-samui';

-- Policies are modified in place (ALTER POLICY, then renamed to say what they now do) rather than dropped and
-- recreated, so there is never a moment when a table has no read rule.
alter policy "swipe_decks: allowed profiles can read" on swipe_decks rename to "swipe_decks: read if allowed";
alter policy "swipe_decks: read if allowed" on swipe_decks
  using (
    auth.uid() in (select id from profiles)
    and (
      feature is null
      or exists (
        select 1 from feature_access fa
        where fa.profile_id = auth.uid() and fa.feature = swipe_decks.feature
      )
    )
  );

alter policy "swipe_cards: allowed profiles can read" on swipe_cards rename to "swipe_cards: read if deck visible";
alter policy "swipe_cards: read if deck visible" on swipe_cards
  using (
    auth.uid() in (select id from profiles)
    and exists (select 1 from swipe_decks d where d.id = swipe_cards.deck_id)
  );

alter policy "swipes: allowed profiles can read" on swipes rename to "swipes: read if card visible";
alter policy "swipes: read if card visible" on swipes
  using (
    auth.uid() in (select id from profiles)
    and exists (select 1 from swipe_cards c where c.id = swipes.card_id)
  );

alter policy "swipes: write own" on swipes rename to "swipes: write own on visible cards";
alter policy "swipes: write own on visible cards" on swipes
  with check (
    profile_id = auth.uid()
    and auth.uid() in (select id from profiles)
    and exists (select 1 from swipe_cards c where c.id = swipes.card_id)
  );

insert into swipe_decks (key, label, description, sort_order, destination, feature) values ($q$honeymoon-maldives$q$, $q$Honeymoon: Maldives$q$, $q$What do we each want out of 20-25 Feb 2027 in the Maldives? Swipe right for yes, left for no.$q$, 20, $q$maldives$q$, $q$maldives$q$);
insert into swipe_cards (deck_id, title, subtitle, detail, emoji, category, image_url, image_credit, image_source_url, facts, links, sort_order)
select d.id, c.title, c.subtitle, c.detail, c.emoji, c.category, c.image_url, c.image_credit, c.image_source_url, c.facts::jsonb, c.links::jsonb, c.sort_order
from swipe_decks d,
(values
  ($q$Local island guesthouse$q$, $q$Island life at the lowest cost$q$, $q$A boutique guesthouse on Maafushi, Thulusdhoo or Dhigurah, with sandbank, dolphin and sunset trips arranged for you. Cheapest way to do the Maldives, about ₹2.0L all-in, but no alcohol on local islands.$q$, $q$🏝️$q$, $q$Stay$q$, $q$maldives/beach.jpg$q$, $q$Photo: Adam Jones from Kelowna, BC, Canada, CC BY-SA 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Beach_Scene_-_Maafushi_Island_-_South_Male_Atoll_-_Maldives_-_02_(14272889946).jpg$q$, $q$[{"label": "Typical price", "value": "About $90-130 a night"}, {"label": "Green tax", "value": "About $6 per person per night"}, {"label": "Total trip", "value": "About ₹2.0L"}]$q$, $q$[{"label": "Guesthouse vs resort cost", "url": "https://amaldives.com/blog/maldives-guesthouse-vs-resort-cost-2026"}, {"label": "Maafushi, map", "url": "https://www.google.com/maps/search/?api=1&query=Maafushi+Maldives"}]$q$, 1),
  ($q$Half-board resort$q$, $q$Lagoon, jetty and spa on one island$q$, $q$A 4-star resort within about an hour by speedboat, with half board. Pool, spa, sandbank picnic and a beach dinner. About ₹3.35L all-in in February.$q$, $q$🏖️$q$, $q$Stay$q$, $q$maldives/aerial.jpg$q$, $q$Photo: Matheenfaiz, CC BY-SA 4.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Anantara_Kihavah_-_Aerial_Hero_Shot_2024.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹18-32k a night"}, {"label": "Green tax", "value": "About $12 per person per night"}, {"label": "Total trip", "value": "About ₹3.35L"}]$q$, $q$[{"label": "Packages and prices", "url": "https://resortlife.travel/india/maldives-packages"}, {"label": "Transfer costs", "url": "https://letsgomaldives.com/blogs/maldives-airport-transfer-costs/"}]$q$, 2),
  ($q$All-inclusive resort$q$, $q$Meals and drinks in one price$q$, $q$Everything included: meals, soft and alcoholic drinks and some activities. The most worry-free, but about ₹4.4L, which is over the ₹4L cap unless February rates land at the low end.$q$, $q$🍹$q$, $q$Stay$q$, $q$maldives/hero.jpg$q$, $q$Photo: dronepicr, CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Malediven_Sandbank_(28800504836).jpg$q$, $q$[{"label": "Package", "value": "About ₹2.85-4.45L for five nights"}, {"label": "Trip total", "value": "About ₹4.4L"}, {"label": "Catch", "value": "Over the cap in February"}]$q$, $q$[{"label": "Value all-inclusive packages", "url": "https://resortlife.travel/india/maldives-packages"}]$q$, 3),
  ($q$Beachfront room$q$, $q$Step from the room onto the sand$q$, $q$Choose a place with direct beach access so mornings start on the sand. Local islands have a designated bikini beach; resorts have private stretches.$q$, $q$🌊$q$, $q$Stay$q$, $q$maldives/beach.jpg$q$, $q$Photo: Adam Jones from Kelowna, BC, Canada, CC BY-SA 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Beach_Scene_-_Maafushi_Island_-_South_Male_Atoll_-_Maldives_-_02_(14272889946).jpg$q$, $q$[{"label": "Look for", "value": "Beach access, shade, a jetty"}, {"label": "Local islands", "value": "Swimwear only on the designated beach"}]$q$, $q$[{"label": "Maldives travel guide", "url": "https://en.wikivoyage.org/wiki/Maldives"}]$q$, 4),
  ($q$Overwater villa$q$, $q$The classic honeymoon photo$q$, $q$Steps into the lagoon from your own deck. Usually 5-star prices, so it pushes the trip past the ₹4L cap in February.$q$, $q$🛖$q$, $q$Stay$q$, $q$maldives/hero.jpg$q$, $q$Photo: dronepicr, CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Malediven_Sandbank_(28800504836).jpg$q$, $q$[{"label": "Typical price", "value": "From about ₹45k a night"}, {"label": "Fits ₹4L?", "value": "No, unless a package is low"}]$q$, $q$[{"label": "Value vs luxury tiers", "url": "https://resortlife.travel/india/maldives-packages"}]$q$, 5),
  ($q$Adults-only resort$q$, $q$Quiet and couple-focused$q$, $q$No children, calmer pools and dining. Fewer options at the budget end of the Maldives, so check availability for 20-25 Feb.$q$, $q$💑$q$, $q$Stay$q$, $q$maldives/aerial.jpg$q$, $q$Photo: Matheenfaiz, CC BY-SA 4.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Anantara_Kihavah_-_Aerial_Hero_Shot_2024.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹25-40k a night"}, {"label": "Best for", "value": "Quiet, long dinners"}]$q$, $q$[{"label": "Search resorts", "url": "https://www.google.com/search?q=adults+only+resort+Maldives+speedboat"}]$q$, 6),
  ($q$Keep the stay modest$q$, $q$Spend on experiences instead$q$, $q$A simple guesthouse and put the saving into the sandbank trip, the dolphin cruise and a special dinner. The ₹4L cap leaves about ₹2L spare.$q$, $q$💸$q$, $q$Stay$q$, $q$maldives/hammocks.jpg$q$, $q$Photo: Buiobuione, CC BY-SA 4.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Buiobuione-Maldive-Maafushi-Town-hammock.jpg$q$, $q$[{"label": "Total trip", "value": "About ₹2.0L"}, {"label": "Spare", "value": "About ₹2L"}]$q$, $q$[{"label": "Guesthouse vs resort cost", "url": "https://amaldives.com/blog/maldives-guesthouse-vs-resort-cost-2026"}]$q$, 7),
  ($q$Stay put all 5 nights$q$, $q$One base, unpack once$q$, $q$Island hopping adds boat transfers. One island keeps things simple, except for the last night near the airport on the early flight.$q$, $q$🧳$q$, $q$Stay$q$, $q$maldives/hammocks.jpg$q$, $q$Photo: Buiobuione, CC BY-SA 4.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Buiobuione-Maldive-Maafushi-Town-hammock.jpg$q$, $q$[{"label": "Exception", "value": "Last night near Malé airport"}, {"label": "Benefit", "value": "No repeated transfers"}]$q$, $q$[{"label": "Transfer costs", "url": "https://letsgomaldives.com/blogs/maldives-airport-transfer-costs/"}]$q$, 8),
  ($q$Couples spa$q$, $q$Massage side by side$q$, $q$Island spas and resort spas both offer couples treatments. Resort spas cost more; guesthouse islands have a few good small ones.$q$, $q$💆$q$, $q$Relax and romance$q$, $q$maldives/sunset.jpg$q$, $q$Photo: Fredrik Rubensson, CC BY-SA 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Maldives_2011_sunset.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹4-12k each (an estimate)"}, {"label": "Book", "value": "A day ahead"}]$q$, $q$[{"label": "Spas, map", "url": "https://www.google.com/maps/search/?api=1&query=couples+spa+Maldives"}]$q$, 9),
  ($q$Sandbank picnic$q$, $q$A strip of sand in the lagoon$q$, $q$A boat takes you to a bare sandbank for a picnic, usually about two hours. Guesthouses and resorts arrange them for roughly $20-50 each.$q$, $q$🏝️$q$, $q$Relax and romance$q$, $q$maldives/sandbank.jpg$q$, $q$Photo: MBraun Germany, CC BY-SA 3.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Kuramathi_Sandbank_001.jpg$q$, $q$[{"label": "Typical price", "value": "About $20-50 each"}, {"label": "Duration", "value": "About 2 hours"}, {"label": "Best time", "value": "Afternoon light"}]$q$, $q$[{"label": "Excursion costs", "url": "https://amaldives.com/blog/maldives-guesthouse-vs-resort-cost-2026"}]$q$, 10),
  ($q$Candlelit beach dinner$q$, $q$A table for two on the sand$q$, $q$Most guesthouses and resorts set one up, with grilled fish or lobster. Tell them about veg needs in advance.$q$, $q$🕯️$q$, $q$Relax and romance$q$, $q$maldives/sunset.jpg$q$, $q$Photo: Fredrik Rubensson, CC BY-SA 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Maldives_2011_sunset.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹6-15k for two"}, {"label": "Book", "value": "1-2 days ahead"}]$q$, $q$[{"label": "Maldives travel guide", "url": "https://en.wikivoyage.org/wiki/Maldives"}]$q$, 11),
  ($q$Sunset dhoni cruise$q$, $q$Drinks on a traditional boat at dusk$q$, $q$A slow boat on the lagoon at sunset, often combined with dolphin watching. Relaxed, not sporty.$q$, $q$⛵$q$, $q$Relax and romance$q$, $q$maldives/dhoni.jpg$q$, $q$Photo: ╚ DD╔ from Male, Maldives, CC BY-SA 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Dhoani_(451985358).jpg$q$, $q$[{"label": "Typical price", "value": "About $20-50 each"}, {"label": "Duration", "value": "2-3 hours"}]$q$, $q$[{"label": "Sunset cruises", "url": "https://www.google.com/search?q=Maldives+sunset+dhoni+cruise"}]$q$, 12),
  ($q$A full do-nothing day$q$, $q$Hammock, book, nap$q$, $q$One day with nothing planned. After the wedding and a travel day it is often the day you want most.$q$, $q$🛋️$q$, $q$Relax and romance$q$, $q$maldives/hammocks.jpg$q$, $q$Photo: Buiobuione, CC BY-SA 4.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Buiobuione-Maldive-Maafushi-Town-hammock.jpg$q$, $q$[{"label": "Cost", "value": "Free"}, {"label": "Pairs with", "value": "A late lunch and a spa evening"}]$q$, $q$[{"label": "Maldives travel guide", "url": "https://en.wikivoyage.org/wiki/Maldives"}]$q$, 13),
  ($q$Golden-hour photos$q$, $q$Couple portraits on the beach$q$, $q$The lagoon at sunset is the photo of the trip. Ask a local photographer or the resort about a one-hour session.$q$, $q$📸$q$, $q$Relax and romance$q$, $q$maldives/sunset.jpg$q$, $q$Photo: Fredrik Rubensson, CC BY-SA 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Maldives_2011_sunset.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹8-20k (an estimate)"}, {"label": "Best light", "value": "Shortly before sunset"}]$q$, $q$[{"label": "Photographers", "url": "https://www.google.com/search?q=Maldives+couple+photo+shoot"}]$q$, 14),
  ($q$Dolphin watching$q$, $q$Dolphins at dusk$q$, $q$A boat trip to spot spinner dolphins in the evening. Not guaranteed, but common in the lagoons.$q$, $q$🐬$q$, $q$Explore$q$, $q$maldives/dolphins.jpg$q$, $q$Photo: bielyvlk, CC BY-SA 3.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:How_many_dolphins_you_see_-_panoramio.jpg$q$, $q$[{"label": "Typical price", "value": "About $20-50 each"}, {"label": "Duration", "value": "About 1-2 hours"}]$q$, $q$[{"label": "Excursion costs", "url": "https://amaldives.com/blog/maldives-guesthouse-vs-resort-cost-2026"}]$q$, 15),
  ($q$Malé market day$q$, $q$Fish market and local streets$q$, $q$Malé has a busy fish market, a local produce market, Sultan Park and the waterfront. The best chance for markets on this trip.$q$, $q$🐟$q$, $q$Explore$q$, $q$maldives/market.jpg$q$, $q$Photo: Buiobuione, CC BY-SA 4.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Buiobuione_Mal%C3%A9_fish_market.jpg$q$, $q$[{"label": "Cost", "value": "Free to walk; food about ₹200-800 each"}, {"label": "Best time", "value": "Morning"}]$q$, $q$[{"label": "Malé on Wikipedia", "url": "https://en.wikipedia.org/wiki/Mal%C3%A9"}, {"label": "Fish market, map", "url": "https://www.google.com/maps/search/?api=1&query=Mal%C3%A9+Fish+Market"}]$q$, 16),
  ($q$Local island village walk$q$, $q$Shops, cafés and the sea$q$, $q$A walk around the island, a café, school-kids on the beach and fishing boats. Slow and real.$q$, $q$🚶$q$, $q$Explore$q$, $q$maldives/beach.jpg$q$, $q$Photo: Adam Jones from Kelowna, BC, Canada, CC BY-SA 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Beach_Scene_-_Maafushi_Island_-_South_Male_Atoll_-_Maldives_-_02_(14272889946).jpg$q$, $q$[{"label": "Cost", "value": "Free"}, {"label": "Time", "value": "1-2 hours"}]$q$, $q$[{"label": "Maafushi, map", "url": "https://www.google.com/maps/search/?api=1&query=Maafushi+Maldives"}]$q$, 17),
  ($q$Sketch the lagoon colours$q$, $q$Paints and a view, no phone$q$, $q$Few galleries or classes, but the water is the subject. Bring a travel watercolour set and a small sketchbook.$q$, $q$🎨$q$, $q$Explore$q$, $q$maldives/hero.jpg$q$, $q$Photo: dronepicr, CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Malediven_Sandbank_(28800504836).jpg$q$, $q$[{"label": "Cost", "value": "Supplies about ₹1-2k"}, {"label": "Best spot", "value": "Beach, jetty or sandbank"}]$q$, $q$[{"label": "Maldives travel guide", "url": "https://en.wikivoyage.org/wiki/Maldives"}]$q$, 18),
  ($q$Seaplane transfer$q$, $q$Views from the air$q$, $q$Spectacular, but seaplanes only fly in daylight, so a mid-afternoon landing rules it out for the first day. Expensive for the Rs 4L cap.$q$, $q$✈️$q$, $q$Explore$q$, $q$maldives/seaplane.jpg$q$, $q$Photo: 7777777kz, CC BY 3.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:ATC_Dr,_Maldives_-_panoramio.jpg$q$, $q$[{"label": "Typical price", "value": "About $200-400 per person round trip"}, {"label": "Catch", "value": "Too late on arrival day"}]$q$, $q$[{"label": "Transfer costs", "url": "https://letsgomaldives.com/blogs/maldives-airport-transfer-costs/"}]$q$, 19),
  ($q$Fresh tuna and seafood BBQ$q$, $q$The catch of the day$q$, $q$Tuna in many forms, grilled fish, lobster, and curries with rice. Tuna is the staple, so non-veg is easy.$q$, $q$🐟$q$, $q$Food and markets$q$, $q$maldives/market.jpg$q$, $q$Photo: Buiobuione, CC BY-SA 4.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Buiobuione_Mal%C3%A9_fish_market.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹1-2.5k per person"}, {"label": "Veg option", "value": "Ask a day ahead"}]$q$, $q$[{"label": "Maldives travel guide", "url": "https://en.wikivoyage.org/wiki/Maldives"}]$q$, 20),
  ($q$Mas huni and a Maldivian breakfast$q$, $q$Tuna, coconut and flatbread$q$, $q$A traditional breakfast of shredded tuna with coconut and onion, eaten with roshi (flatbread). Veg alternatives are available if you ask.$q$, $q$🥥$q$, $q$Food and markets$q$, $q$maldives/market.jpg$q$, $q$Photo: Buiobuione, CC BY-SA 4.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Buiobuione_Mal%C3%A9_fish_market.jpg$q$, $q$[{"label": "Typical price", "value": "Included at most guesthouses"}, {"label": "Veg option", "value": "Ask for veg roshi and fruit"}]$q$, $q$[{"label": "Maldives travel guide", "url": "https://en.wikivoyage.org/wiki/Maldives"}]$q$, 21),
  ($q$Indian dinner in Malé$q$, $q$Familiar food, vegetarian included$q$, $q$Malé has Indian restaurants with proper veg thalis. A good break on the last evening if one of you wants something familiar.$q$, $q$🍛$q$, $q$Food and markets$q$, $q$maldives/male.jpg$q$, $q$Photo: Shahee Ilyas, CC BY-SA 3.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Male-total.jpg$q$, $q$[{"label": "Where", "value": "Malé or Hulhumalé"}, {"label": "Typical price", "value": "About ₹1-2k per person"}]$q$, $q$[{"label": "Indian restaurants, map", "url": "https://www.google.com/maps/search/?api=1&query=Indian+vegetarian+restaurant+Mal%C3%A9"}]$q$, 22),
  ($q$Cafés and short eats$q$, $q$Hedhikaa with sweet tea$q$, $q$Small fried snacks (hedhikaa) with tea in a local café. Cheap and a good way to try local flavours.$q$, $q$☕$q$, $q$Food and markets$q$, $q$maldives/male.jpg$q$, $q$Photo: Shahee Ilyas, CC BY-SA 3.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Male-total.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹100-400"}, {"label": "Where", "value": "Local islands and Malé"}]$q$, $q$[{"label": "Cafés, map", "url": "https://www.google.com/maps/search/?api=1&query=caf%C3%A9+Maafushi+Maldives"}]$q$, 23),
  ($q$Cheapest flights: via Mumbai$q$, $q$Delhi 09:30, one ticket$q$, $q$IndiGo Delhi to Malé via Mumbai, lands 15:45. ₹32,666 for two one-way. The cheapest option, and a single ticket so connections are covered.$q$, $q$✈️$q$, $q$Flights$q$, $q$maldives/male.jpg$q$, $q$Photo: Shahee Ilyas, CC BY-SA 3.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Male-total.jpg$q$, $q$[{"label": "Out", "value": "₹32,666 for two"}, {"label": "Lands", "value": "15:45 Malé time"}]$q$, $q$[{"label": "Delhi to Malé flights", "url": "https://www.google.com/travel/flights?q=Flights%20from%20DEL%20to%20MLE%20on%202027-02-20"}]$q$, 24),
  ($q$Nonstop out: Air India$q$, $q$Lands 11:50, same-day seaplane possible$q$, $q$Delhi to Malé nonstop (about 4h20) is about ₹57,156 for two. Earlier landing makes a seaplane transfer possible on arrival day, at extra cost.$q$, $q$🛫$q$, $q$Flights$q$, $q$maldives/seaplane.jpg$q$, $q$Photo: 7777777kz, CC BY 3.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:ATC_Dr,_Maldives_-_panoramio.jpg$q$, $q$[{"label": "Out", "value": "₹57,156 for two"}, {"label": "Lands", "value": "11:50 Malé time"}, {"label": "Extra", "value": "About ₹24k more than via Mumbai"}]$q$, $q$[{"label": "Delhi to Malé flights", "url": "https://www.google.com/travel/flights?q=Flights%20from%20DEL%20to%20MLE%20on%202027-02-20"}]$q$, 25),
  ($q$Early flight home (09:15)$q$, $q$Cheapest return, 06:15 airport start$q$, $q$IndiGo Malé to Kolkata via Mumbai, lands 17:50, ₹53,942 for two. Needs a night near the airport and a 06:15 airport start.$q$, $q$⏰$q$, $q$Flights$q$, $q$maldives/male.jpg$q$, $q$Photo: Shahee Ilyas, CC BY-SA 3.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Male-total.jpg$q$, $q$[{"label": "Back", "value": "₹53,942 for two"}, {"label": "Lands", "value": "17:50 Kolkata"}, {"label": "Night before", "value": "Near Malé airport"}]$q$, $q$[{"label": "Malé to Kolkata flights", "url": "https://www.google.com/travel/flights?q=Flights%20from%20MLE%20to%20CCU%20on%202027-02-25"}]$q$, 26),
  ($q$Relaxed flight home (16:00)$q$, $q$No pre-dawn start, lands 23:45$q$, $q$IndiGo Malé to Kolkata via Bengaluru, ₹57,220 for two. A slow last morning, but you land in Kolkata at 23:45.$q$, $q$🌙$q$, $q$Flights$q$, $q$maldives/dhoni.jpg$q$, $q$Photo: ╚ DD╔ from Male, Maldives, CC BY-SA 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Dhoani_(451985358).jpg$q$, $q$[{"label": "Back", "value": "₹57,220 for two"}, {"label": "Lands", "value": "23:45 Kolkata"}]$q$, $q$[{"label": "Malé to Kolkata flights", "url": "https://www.google.com/travel/flights?q=Flights%20from%20MLE%20to%20CCU%20on%202027-02-25"}]$q$, 27)
) as c(title, subtitle, detail, emoji, category, image_url, image_credit, image_source_url, facts, links, sort_order)
where d.key = $q$honeymoon-maldives$q$;

insert into swipe_decks (key, label, description, sort_order, destination, feature) values ($q$honeymoon-mauritius$q$, $q$Honeymoon: Mauritius$q$, $q$What do we each want out of 20-25 Feb 2027 in Mauritius? Swipe right for yes, left for no.$q$, 30, $q$mauritius$q$, $q$mauritius$q$);
insert into swipe_cards (deck_id, title, subtitle, detail, emoji, category, image_url, image_credit, image_source_url, facts, links, sort_order)
select d.id, c.title, c.subtitle, c.detail, c.emoji, c.category, c.image_url, c.image_credit, c.image_source_url, c.facts::jsonb, c.links::jsonb, c.sort_order
from swipe_decks d,
(values
  ($q$Boutique stay on the north coast$q$, $q$Trou aux Biches or Grand Baie$q$, $q$A well-rated boutique hotel or guesthouse near calm lagoons, with a driver for sightseeing. About ₹3.15L all-in (estimate).$q$, $q$🏡$q$, $q$Stay$q$, $q$mauritius/beach.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Aerial_view_of_the_Trou_aux_Biches_Beach_in_Mauritius,_as_seen_from_the_south_(53698114274).jpg$q$, $q$[{"label": "Typical price", "value": "About ₹10-15k a night (estimate)"}, {"label": "Total trip", "value": "About ₹3.15L"}]$q$, $q$[{"label": "Trou aux Biches, map", "url": "https://www.google.com/maps/search/?api=1&query=Trou+aux+Biches+Mauritius"}, {"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 1),
  ($q$Beach resort, half board$q$, $q$Pool, lagoon, dinner sorted$q$, $q$A 4-star beach resort on the north or west coast with half board. About ₹3.45L all-in (estimate), February is peak.$q$, $q$🏖️$q$, $q$Stay$q$, $q$mauritius/lemorne.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Le_Morne_Beach_with_Le_Morne_Brabant_Mountain_in_the_background,_Mauritius_(53698223315).jpg$q$, $q$[{"label": "Typical price", "value": "About ₹20-30k a night (estimate)"}, {"label": "Total trip", "value": "About ₹3.45L"}]$q$, $q$[{"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 2),
  ($q$5-star beach resort$q$, $q$Spa and a private dinner$q$, $q$The most indulgent version, about ₹4.6L (estimate), which is about ₹60k over the ₹4L cap.$q$, $q$✨$q$, $q$Stay$q$, $q$mauritius/lemorne.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Le_Morne_Beach_with_Le_Morne_Brabant_Mountain_in_the_background,_Mauritius_(53698223315).jpg$q$, $q$[{"label": "Typical price", "value": "About ₹40-60k a night (estimate)"}, {"label": "Total trip", "value": "About ₹4.6L, over the cap"}]$q$, $q$[{"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 3),
  ($q$West coast near Le Morne$q$, $q$Mountain views, quiet beaches$q$, $q$The south-west is the scenic corner: Le Morne mountain, a long lagoon, and the Chamarel area closer by. Further from Port Louis.$q$, $q$⛰️$q$, $q$Stay$q$, $q$mauritius/lemorne.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Le_Morne_Beach_with_Le_Morne_Brabant_Mountain_in_the_background,_Mauritius_(53698223315).jpg$q$, $q$[{"label": "Trade-off", "value": "Further from Port Louis"}, {"label": "Best for", "value": "Views and quiet"}]$q$, $q$[{"label": "Le Morne, map", "url": "https://www.google.com/maps/search/?api=1&query=Le+Morne+Mauritius"}]$q$, 4),
  ($q$Stay put all 5 nights$q$, $q$One base, unpack once$q$, $q$Mauritius is small enough (about 1-2 hours across) that one base works for the markets, the south and the beaches with day trips.$q$, $q$🧳$q$, $q$Stay$q$, $q$mauritius/beach.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Aerial_view_of_the_Trou_aux_Biches_Beach_in_Mauritius,_as_seen_from_the_south_(53698114274).jpg$q$, $q$[{"label": "Island size", "value": "About 1-2 hours across by road"}, {"label": "Benefit", "value": "No packing"}]$q$, $q$[{"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 5),
  ($q$Keep the stay modest$q$, $q$Spend on experiences instead$q$, $q$A simple boutique stay and a driver for the sightseeing days leaves about ₹85k spare in the ₹4L cap.$q$, $q$💸$q$, $q$Stay$q$, $q$mauritius/beach.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Aerial_view_of_the_Trou_aux_Biches_Beach_in_Mauritius,_as_seen_from_the_south_(53698114274).jpg$q$, $q$[{"label": "Total trip", "value": "About ₹3.15L"}, {"label": "Spare", "value": "About ₹85k"}]$q$, $q$[{"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 6),
  ($q$Couples spa$q$, $q$Massage side by side$q$, $q$Resort and boutique spas offer couples treatments. Resort spas cost more.$q$, $q$💆$q$, $q$Relax and romance$q$, $q$mauritius/sunset.jpg$q$, $q$Photo: Dennis Sylvester Hurd, CC0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:A_Sunday_Sunset_-_Flic-en-Flac.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹4-12k each (estimate)"}, {"label": "Book", "value": "A day ahead"}]$q$, $q$[{"label": "Spas, map", "url": "https://www.google.com/maps/search/?api=1&query=couples+spa+Mauritius"}]$q$, 7),
  ($q$Private beach dinner$q$, $q$A table for two by the sea$q$, $q$Many resorts arrange one, with grilled fish and a quiet beach. Tell them about veg needs in advance.$q$, $q$🕯️$q$, $q$Relax and romance$q$, $q$mauritius/sunset.jpg$q$, $q$Photo: Dennis Sylvester Hurd, CC0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:A_Sunday_Sunset_-_Flic-en-Flac.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹8-20k for two (estimate)"}, {"label": "Book", "value": "1-2 days ahead"}]$q$, $q$[{"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 8),
  ($q$Sunset at Flic en Flac$q$, $q$West-coast sunsets$q$, $q$The west coast faces the sunset, and Flic en Flac is the classic spot for it. A short walk on the beach is enough.$q$, $q$🌅$q$, $q$Relax and romance$q$, $q$mauritius/sunset.jpg$q$, $q$Photo: Dennis Sylvester Hurd, CC0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:A_Sunday_Sunset_-_Flic-en-Flac.jpg$q$, $q$[{"label": "Cost", "value": "Free"}, {"label": "Best time", "value": "Just before sunset"}]$q$, $q$[{"label": "Flic en Flac, map", "url": "https://www.google.com/maps/search/?api=1&query=Flic+en+Flac+Beach+Mauritius"}]$q$, 9),
  ($q$A full do-nothing day$q$, $q$Lagoon, book, nap$q$, $q$One day with nothing planned. Mauritius has a lot to see, so protect at least one slow day.$q$, $q$🛋️$q$, $q$Relax and romance$q$, $q$mauritius/beach.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Aerial_view_of_the_Trou_aux_Biches_Beach_in_Mauritius,_as_seen_from_the_south_(53698114274).jpg$q$, $q$[{"label": "Cost", "value": "Free"}, {"label": "Pairs with", "value": "A long lunch"}]$q$, $q$[{"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 10),
  ($q$Golden-hour photos$q$, $q$Couple portraits by the lagoon$q$, $q$The lagoon, a beach or Le Morne make good backdrops. Ask a local photographer about a one-hour session.$q$, $q$📸$q$, $q$Relax and romance$q$, $q$mauritius/sunset.jpg$q$, $q$Photo: Dennis Sylvester Hurd, CC0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:A_Sunday_Sunset_-_Flic-en-Flac.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹8-20k (estimate)"}, {"label": "Best light", "value": "Shortly before sunset"}]$q$, $q$[{"label": "Photographers", "url": "https://www.google.com/search?q=Mauritius+couple+photo+shoot"}]$q$, 11),
  ($q$Sketch the lagoon$q$, $q$Paints and a view$q$, $q$Bring a travel watercolour set. The lagoon, Le Morne and Chamarel are all good subjects.$q$, $q$🎨$q$, $q$Relax and romance$q$, $q$mauritius/beach.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Aerial_view_of_the_Trou_aux_Biches_Beach_in_Mauritius,_as_seen_from_the_south_(53698114274).jpg$q$, $q$[{"label": "Cost", "value": "Supplies about ₹1-2k"}, {"label": "Best spots", "value": "Beach, Le Morne, Chamarel"}]$q$, $q$[{"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 12),
  ($q$Port Louis Central Market$q$, $q$Spices, herbal teas, street snacks$q$, $q$The capital’s central market is the place for local flavours and souvenirs. Go on a weekday morning.$q$, $q$🧺$q$, $q$Explore$q$, $q$mauritius/market.jpg$q$, $q$Photo: Sushil Dawka, CC BY-SA 4.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Herbal_tisanes_for_several_ailments_on_sale_at_the_Central_Market,_Port_Louis,_Mauritius.jpg$q$, $q$[{"label": "Cost", "value": "Free; snacks about ₹200-600"}, {"label": "Best time", "value": "Weekday morning"}]$q$, $q$[{"label": "Central Market, map", "url": "https://www.google.com/maps/search/?api=1&query=Central+Market+Port+Louis"}, {"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 13),
  ($q$Blue Penny Museum$q$, $q$Art and history at the waterfront$q$, $q$A small museum at the Caudan Waterfront, known for the rare Mauritius stamps and for paintings and maps of the island.$q$, $q$🎨$q$, $q$Explore$q$, $q$mauritius/waterfront.jpg$q$, $q$Photo: Benoît Prieur, CC0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Caudan_Waterfront_(Port_Louis),_vue_d%27un_canal.jpg$q$, $q$[{"label": "Time", "value": "About 1 hour"}, {"label": "Where", "value": "Caudan Waterfront, Port Louis"}]$q$, $q$[{"label": "Blue Penny Museum", "url": "https://en.wikipedia.org/wiki/Blue_Penny_Museum"}, {"label": "Museum, map", "url": "https://www.google.com/maps/search/?api=1&query=Blue+Penny+Museum+Port+Louis"}]$q$, 14),
  ($q$Aapravasi Ghat$q$, $q$A UNESCO heritage site$q$, $q$Where indentured labourers arrived from India in the 1800s. A short, moving visit that is also a link to Indian heritage.$q$, $q$🏛️$q$, $q$Explore$q$, $q$mauritius/waterfront.jpg$q$, $q$Photo: Benoît Prieur, CC0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Caudan_Waterfront_(Port_Louis),_vue_d%27un_canal.jpg$q$, $q$[{"label": "Time", "value": "About 1 hour"}, {"label": "Where", "value": "Port Louis"}]$q$, $q$[{"label": "Aapravasi Ghat", "url": "https://en.wikipedia.org/wiki/Aapravasi_Ghat"}, {"label": "Site, map", "url": "https://www.google.com/maps/search/?api=1&query=Aapravasi+Ghat+Port+Louis"}]$q$, 15),
  ($q$Chamarel Seven Coloured Earths$q$, $q$The view day$q$, $q$Dunes of coloured earth and a tall waterfall in the south-west. Easiest with a driver for the day.$q$, $q$🌈$q$, $q$Explore$q$, $q$mauritius/chamarel.jpg$q$, $q$Photo: CEphoto, Uwe Aranas, CC BY-SA 3.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Mauritius_Seven-Coloured-Earths-01.jpg$q$, $q$[{"label": "Driver", "value": "About ₹4k for the day (estimate)"}, {"label": "Time", "value": "Half to full day"}]$q$, $q$[{"label": "Chamarel", "url": "https://en.wikipedia.org/wiki/Chamarel"}, {"label": "Seven Coloured Earths, map", "url": "https://www.google.com/maps/search/?api=1&query=Chamarel+Seven+Coloured+Earth"}]$q$, 16),
  ($q$Le Morne viewpoint$q$, $q$The mountain over the lagoon$q$, $q$A UNESCO mountain at the south-west tip. The viewpoint and beach make a good stop on the way back from Chamarel.$q$, $q$⛰️$q$, $q$Explore$q$, $q$mauritius/lemorne.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Le_Morne_Beach_with_Le_Morne_Brabant_Mountain_in_the_background,_Mauritius_(53698223315).jpg$q$, $q$[{"label": "Time", "value": "About 1 hour"}, {"label": "Best time", "value": "Morning or late afternoon"}]$q$, $q$[{"label": "Le Morne, map", "url": "https://www.google.com/maps/search/?api=1&query=Le+Morne+Brabant+Mauritius"}]$q$, 17),
  ($q$Pamplemousses garden$q$, $q$Giant water lilies$q$, $q$A famous botanical garden north of Port Louis with a pond of giant water lilies. Easy and photogenic.$q$, $q$🌿$q$, $q$Explore$q$, $q$mauritius/garden.jpg$q$, $q$Photo: Condem at English Wikipedia, Public domain, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Giant_water_lilies.JPG$q$, $q$[{"label": "Time", "value": "1-2 hours"}, {"label": "Where", "value": "Pamplemousses, north"}]$q$, $q$[{"label": "Garden, map", "url": "https://www.google.com/maps/search/?api=1&query=Pamplemousses+Botanical+Garden+Mauritius"}]$q$, 18),
  ($q$Grand Bassin (Ganga Talao)$q$, $q$A sacred crater lake$q$, $q$A Hindu pilgrimage site in a crater lake with temples and large statues. Feels very familiar to visitors from India.$q$, $q$🛕$q$, $q$Explore$q$, $q$mauritius/temple.jpg$q$, $q$Photo: carrotmadman6 from Mauritius, CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Ganga_Talao_(5489050038).jpg$q$, $q$[{"label": "Time", "value": "About 1 hour"}, {"label": "Dress", "value": "Modest clothing"}]$q$, $q$[{"label": "Grand Bassin, map", "url": "https://www.google.com/maps/search/?api=1&query=Ganga+Talao+Grand+Bassin+Mauritius"}]$q$, 19),
  ($q$Hire a driver for the day$q$, $q$See the south at your pace$q$, $q$A car and driver for the sightseeing days makes Chamarel, Le Morne and Port Louis easy.$q$, $q$🚗$q$, $q$Explore$q$, $q$mauritius/chamarel.jpg$q$, $q$Photo: CEphoto, Uwe Aranas, CC BY-SA 3.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Mauritius_Seven-Coloured-Earths-01.jpg$q$, $q$[{"label": "Price", "value": "About ₹4k a day (estimate)"}, {"label": "Good days", "value": "Port Louis and Chamarel"}]$q$, $q$[{"label": "Private drivers", "url": "https://www.google.com/search?q=Mauritius+private+driver+tour"}]$q$, 20),
  ($q$Painting or craft workshop$q$, $q$Make a keepsake$q$, $q$Ask your stay about a painting or craft session. Availability is not checked, so confirm before counting on it.$q$, $q$🖌️$q$, $q$Explore$q$, $q$mauritius/garden.jpg$q$, $q$Photo: Condem at English Wikipedia, Public domain, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Giant_water_lilies.JPG$q$, $q$[{"label": "Typical price", "value": "About ₹2-5k each (estimate)"}, {"label": "Status", "value": "Availability not checked"}]$q$, $q$[{"label": "Art classes", "url": "https://www.google.com/search?q=Mauritius+painting+workshop+tourists"}]$q$, 21),
  ($q$Dholl puri and street food$q$, $q$Mauritian flatbread, snacks$q$, $q$Dholl puri (a split-pea flatbread) and gateaux piments (chilli fritters) are the signature street foods, and both are vegetarian.$q$, $q$🥘$q$, $q$Food and markets$q$, $q$mauritius/market.jpg$q$, $q$Photo: Sushil Dawka, CC BY-SA 4.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Herbal_tisanes_for_several_ailments_on_sale_at_the_Central_Market,_Port_Louis,_Mauritius.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹100-400"}, {"label": "Veg option", "value": "Mostly vegetarian"}]$q$, $q$[{"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 22),
  ($q$Seafood by the lagoon$q$, $q$Fish, octopus curry, prawns$q$, $q$Fresh fish and octopus curry at a beachfront restaurant. Veg dishes are easy to find too.$q$, $q$🦐$q$, $q$Food and markets$q$, $q$mauritius/beach.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Aerial_view_of_the_Trou_aux_Biches_Beach_in_Mauritius,_as_seen_from_the_south_(53698114274).jpg$q$, $q$[{"label": "Typical price", "value": "About ₹1.5-3k per person"}, {"label": "Veg option", "value": "Easy"}]$q$, $q$[{"label": "Beachfront restaurants, map", "url": "https://www.google.com/maps/search/?api=1&query=beachfront+seafood+restaurant+Mauritius"}]$q$, 23),
  ($q$Rum distillery lunch$q$, $q$La Rhumerie de Chamarel$q$, $q$A distillery with a restaurant and tastings near the coloured earth, a natural lunch stop on the Chamarel day.$q$, $q$🥃$q$, $q$Food and markets$q$, $q$mauritius/chamarel.jpg$q$, $q$Photo: CEphoto, Uwe Aranas, CC BY-SA 3.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Mauritius_Seven-Coloured-Earths-01.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹1.5-3k per person"}, {"label": "Pairs with", "value": "Chamarel"}]$q$, $q$[{"label": "Distillery, map", "url": "https://www.google.com/maps/search/?api=1&query=La+Rhumerie+de+Chamarel"}]$q$, 24),
  ($q$Mauritian biryani and curries$q$, $q$Indian, Creole and Chinese$q$, $q$Mauritian cooking blends Indian, Creole and Chinese influences. Both vegetarian and non-vegetarian dishes are easy.$q$, $q$🍛$q$, $q$Food and markets$q$, $q$mauritius/market.jpg$q$, $q$Photo: Sushil Dawka, CC BY-SA 4.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Herbal_tisanes_for_several_ailments_on_sale_at_the_Central_Market,_Port_Louis,_Mauritius.jpg$q$, $q$[{"label": "Typical price", "value": "About ₹500-1.5k per person"}, {"label": "Veg option", "value": "Easy"}]$q$, $q$[{"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 25),
  ($q$Nonstop flight to Mauritius$q$, $q$About 8 hours from Delhi$q$, $q$Air Mauritius flies Delhi to Mauritius nonstop. Round trips run about ₹58-62k per person (estimate from search results).$q$, $q$✈️$q$, $q$Flights$q$, $q$mauritius/hero.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Aerial_view_of_the_southwest_of_Mauritius_(53698214005).jpg$q$, $q$[{"label": "Cost", "value": "About ₹58-62k per person round trip (estimate)"}, {"label": "Time", "value": "About 8 hours"}]$q$, $q$[{"label": "Delhi to Mauritius fares", "url": "https://kayak.co.in/flight-routes/New-Delhi-Indira-Gandhi-Intl-DEL/Mauritius-MU0"}]$q$, 26),
  ($q$One-stop flight home to Kolkata$q$, $q$No direct flight$q$, $q$The way home goes via Delhi or Mumbai, so book it as one ticket and check the connection time.$q$, $q$🔄$q$, $q$Flights$q$, $q$mauritius/hero.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Aerial_view_of_the_southwest_of_Mauritius_(53698214005).jpg$q$, $q$[{"label": "Routing", "value": "Mauritius to Delhi or Mumbai to Kolkata"}, {"label": "Flights total", "value": "About ₹1.4L for two (estimate)"}]$q$, $q$[{"label": "Mauritius travel guide", "url": "https://en.wikivoyage.org/wiki/Mauritius"}]$q$, 27),
  ($q$Travel insurance with cyclone cover$q$, $q$February is cyclone season$q$, $q$January and February are the rainiest months and fall in cyclone season. Insurance that covers cancellations is sensible.$q$, $q$🛡️$q$, $q$Flights$q$, $q$mauritius/hero.jpg$q$, $q$Photo: "dronepicr", CC BY 2.0, via Wikimedia Commons$q$, $q$https://commons.wikimedia.org/wiki/File:Aerial_view_of_the_southwest_of_Mauritius_(53698214005).jpg$q$, $q$[{"label": "Why", "value": "February is cyclone season"}, {"label": "Rain", "value": "Frequent afternoon showers"}]$q$, $q$[{"label": "Best time to visit", "url": "https://www.30sundays.club/blog/best-time-to-visit-mauritius"}]$q$, 28)
) as c(title, subtitle, detail, emoji, category, image_url, image_credit, image_source_url, facts, links, sort_order)
