update trip_alternatives set data = jsonb_set(jsonb_set(jsonb_set(data, '{options,0,timeline}', $q$[{"day":"Sat 20 Feb","kind":"flight","title":"Delhi (DEL) → Malé (MLE)","time":"09:30 → 15:45","detail":"IndiGo via Mumbai, 1h30 layover, one ticket. Lands 15:45 Malé time (the Maldives is 30 minutes behind India).","cost":"₹32,666 for two"},{"day":"Sat 20 Feb","kind":"transfer","title":"Malé airport: immigration, bags, pick-up","time":"15:45","detail":"Visa on arrival is free for Indian passport holders; fill in the traveller declaration beforehand. Ask the guesthouse to meet you at the jetty."},{"day":"Sat 20 Feb","kind":"ferry","title":"Speedboat to your island","time":"17:00","detail":"About 20-60 minutes depending on the island. Speedboats run in daylight, so check the last departure with the guesthouse.","cost":"About $30-40 each way per person"},{"day":"Sat 20 Feb","kind":"hotel","title":"Check in, sunset on the beach","detail":"First of four island nights."},{"day":"Sun 21 Feb","kind":"activity","title":"Beach day and a sandbank picnic by boat","detail":"About 2 hours, arranged by the guesthouse ($20-50 each)."},{"day":"Mon 22 Feb","kind":"activity","title":"Island walk, sketching, and a dolphin cruise at dusk"},{"day":"Tue 23 Feb","kind":"activity","title":"Spa afternoon and a candlelit beach dinner"},{"day":"Wed 24 Feb","kind":"ferry","title":"Ferry or speedboat back to Malé","time":"10:00","detail":"Public ferries are cheaper but slower; speedboats are quicker.","cost":"About $30-40 per person by speedboat"},{"day":"Wed 24 Feb","kind":"activity","title":"Malé fish market, local market and Sultan Park","time":"13:00"},{"day":"Wed 24 Feb","kind":"hotel","title":"Night near the airport (Hulhumalé)","detail":"A simple hotel a few minutes from the airport, about ₹5-8k (an estimate)."},{"day":"Thu 25 Feb","kind":"transfer","title":"At the airport","time":"06:15","detail":"Leave the hotel in time for the 09:15 flight.","warn":"Very early start on the last day."},{"day":"Thu 25 Feb","kind":"flight","title":"Malé (MLE) → Kolkata (CCU)","time":"09:15 → 17:50","detail":"IndiGo via Mumbai, 2h30 layover, one ticket, so the airline covers the connection. Lands 17:50 India time.","cost":"₹53,942 for two"}]$q$::jsonb), '{options,1,timeline}', $q$[{"day":"Sat 20 Feb","kind":"flight","title":"Delhi (DEL) → Malé (MLE)","time":"09:30 → 15:45","detail":"IndiGo via Mumbai, 1h30 layover, one ticket. Lands 15:45 Malé time (the Maldives is 30 minutes behind India).","cost":"₹32,666 for two"},{"day":"Sat 20 Feb","kind":"transfer","title":"Malé airport: immigration, bags, pick-up","time":"15:45","detail":"Visa on arrival is free for Indian passport holders; fill in the traveller declaration beforehand. Pick a resort reached by speedboat: seaplanes have stopped by the time you land. Ask the resort to meet you at the jetty."},{"day":"Sat 20 Feb","kind":"ferry","title":"Speedboat to the resort","time":"17:00","detail":"About 20-60 minutes. Often included in a package; otherwise a few thousand rupees each (an estimate).","cost":"Included in some packages, else about ₹10-25k for two"},{"day":"Sat 20 Feb","kind":"hotel","title":"Check in, first walk on the jetty","detail":"Half board: dinner is included."},{"day":"Sun 21 Feb","kind":"activity","title":"Pool, lagoon and a couples spa"},{"day":"Mon 22 Feb","kind":"activity","title":"Sandbank picnic and a sunset dolphin cruise"},{"day":"Tue 23 Feb","kind":"activity","title":"Private beach dinner"},{"day":"Wed 24 Feb","kind":"activity","title":"The slow last full day; pack early"},{"day":"Thu 25 Feb","kind":"hotel","title":"Slow breakfast, last swim","time":"09:30"},{"day":"Thu 25 Feb","kind":"ferry","title":"Speedboat to Malé airport","time":"12:30","detail":"Check the resort’s boat times, since the boat has to match the 16:00 flight."},{"day":"Thu 25 Feb","kind":"flight","title":"Malé (MLE) → Kolkata (CCU)","time":"16:00 → 23:45","detail":"IndiGo via Bengaluru, 2h35 layover, one ticket. Lands 23:45 Indi