update trip_alternatives set data = jsonb_set(jsonb_set(jsonb_set(data, '{options,0,timeline}', $q$[{"day":"Sat 20 Feb","kind":"flight","title":"Delhi → Mauritius","detail":"Air Mauritius flies it nonstop, about 8 hours. Check the schedule; Mauritius is 1h30 behind India.","cost":"About ₹58-62k per person round trip (estimate)"},{"day":"Sat 20 Feb","kind":"transfer","title":"Airport to your stay on the north coast","detail":"About 45 minutes to 1.5 hours by taxi, depending on the coast.","cost":"About ₹3-5k (estimate)"},{"day":"Sat 20 Feb","kind":"hotel","title":"Check in, sunset by the sea"},{"day":"Sun 21 Feb","kind":"activity","title":"Beach day on the north coast","detail":"Port Louis is quiet on Sundays, so keep this for the lagoon."},{"day":"Mon 22 Feb","kind":"activity","title":"Port Louis: Central Market, Blue Penny Museum, Aapravasi Ghat","detail":"Start early before the heat and the afternoon showers."},{"day":"Tue 23 Feb","kind":"activity","title":"Chamarel and Le Morne with a driver","detail":"About ₹4k for the day (estimate)."},{"day":"Wed 24 Feb","kind":"activity","title":"Pamplemousses garden, a creative session, and the special dinner"},{"day":"Thu 25 Feb","kind":"transfer","title":"Transfer to the airport","detail":"Timing depends on the flights."},{"day":"Thu 25 Feb","kind":"flight","title":"Mauritius → Delhi or Mumbai → Kolkata","detail":"One stop; there is no direct flight to Kolkata, so book it as one ticket and check the connection time.","cost":"Included in the ~₹1.4L flights estimate (not a live quote)","warn":"Mauritius flights are estimates: get live quotes before relying on them."}]$q$::jsonb), '{options,1,timeline}', $q$[{"day":"Sat 20 Feb","kind":"flight","title":"Delhi → Mauritius","detail":"Air Mauritius flies it nonstop, about 8 hours. Check the schedule; Mauritius is 1h30 behind India.","cost":"About ₹58-62k per person round trip (estimate)"},{"day":"Sat 20 Feb","kind":"transfer","title":"Airport to your resort","detail":"About 45 mi